// ❌ Low cohesion: one class does billing, email, and reporting.
// Tight coupling: hard-wired to concrete SqlDatabase and SmtpClient.
public class CustomerManager {
    private readonly SqlConnection _db = new SqlConnection(...);

    public void ProcessOrder(Order o) { /* billing SQL */ }
    public void SendInvoiceEmail(Order o) { /* builds SmtpClient inline */ }
    public void ExportOrdersToCsv(DateTime from) { /* reporting + file IO */ }
    public bool IsPremium(Customer c) => c.LifetimeValue > 10_000;
}
// Any change to email format, DB schema, or report layout all lands here.

// ✅ High cohesion: each class has one job; all dependencies are contracts.
public interface IOrderBilling { Task ChargeAsync(Order o, CancellationToken ct); }
public interface IInvoiceMailer { Task SendAsync(Invoice invoice, CancellationToken ct); }
public interface IOrderReporting { IAsyncEnumerable<Order> QueryAsync(DateRange range); }

public sealed class PremiumEligibility {
    private const decimal Threshold = 10_000m;
    public bool IsEligible(Customer c) => c.LifetimeValue > Threshold;
}

// Changing the email template touches only SmtpInvoiceMailer.
// Swapping SQL for an API client means a new IOrderBilling, nothing else.
